<?php
require_once __DIR__.'/inc/bootstrap.php'; require_login(); require_admin(); require_once __DIR__.'/config/database.php'; require_once __DIR__.'/inc/audit.php';
$pdo=db(); csrf_check();
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action'] ?? '';
  try {
    if ($action==='save') {
      $id=(int)($_POST['id'] ?? 0); $code=trim($_POST['student_code'] ?? ''); $name=trim($_POST['full_name'] ?? ''); $email=filter_var(trim($_POST['email'] ?? ''), FILTER_VALIDATE_EMAIL); $course=trim($_POST['course'] ?? ''); $year=trim($_POST['academic_year'] ?? ''); $status=($_POST['status'] ?? 'active')==='inactive'?'inactive':'active';
      if ($name==='' || !$email || $course==='' || $year==='') throw new RuntimeException('Enter a name, valid email, course and year.');
      if ($id) { $q=$pdo->prepare('UPDATE students SET student_code=?,full_name=?,email=?,course=?,academic_year=?,status=? WHERE id=?'); $q->execute([$code ?: null,$name,$email,$course,$year,$status,$id]); audit_log($pdo,'student.update','Updated student #'.$id); }
      else { $q=$pdo->prepare('INSERT INTO students(student_code,full_name,email,course,academic_year,status) VALUES(?,?,?,?,?,?)'); $q->execute([$code ?: null,$name,$email,$course,$year,$status]); audit_log($pdo,'student.create','Created student '.$email); }
      flash('Student record saved.');
    } elseif ($action==='delete') { $id=(int)($_POST['id'] ?? 0); $q=$pdo->prepare('DELETE FROM students WHERE id=?'); $q->execute([$id]); audit_log($pdo,'student.delete','Deleted student #'.$id); flash('Student record deleted.'); }
  } catch (Throwable $e) { flash($e instanceof PDOException ? 'Could not save: email or student code may already exist.' : $e->getMessage(),'error'); }
  header('Location: students.php'); exit;
}
$edit=null; if(isset($_GET['edit'])) { $q=$pdo->prepare('SELECT * FROM students WHERE id=?'); $q->execute([(int)$_GET['edit']]); $edit=$q->fetch() ?: null; }
$search=trim($_GET['q'] ?? ''); $course=trim($_GET['course'] ?? ''); $sqlq="SELECT * FROM students WHERE (full_name LIKE ? OR email LIKE ? OR COALESCE(student_code,'') LIKE ?)"; $args=['%'.$search.'%','%'.$search.'%','%'.$search.'%']; if($course!==''){ $sqlq.=' AND course=?'; $args[]=$course; } $sqlq.=' ORDER BY id DESC LIMIT 100'; $q=$pdo->prepare($sqlq); $q->execute($args); $students=$q->fetchAll(); $courses=$pdo->query('SELECT DISTINCT course FROM students ORDER BY course')->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Student management'; require __DIR__.'/inc/header.php'; ?>
<div class="page-heading"><div><div class="eyebrow">PRACTICAL 11</div><h1>Student management</h1><p>Add, edit, delete, search and filter student records.</p></div><span class="pill">ADMIN ONLY</span></div>
<section class="panel"><h2><?= $edit?'Edit student':'Add student' ?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Student code<input name="student_code" value="<?=e($edit['student_code']??'')?>" placeholder="GT021"></label><label>Full name<input required name="full_name" value="<?=e($edit['full_name']??'')?>"></label><label>Email<input required type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label>Course<input required name="course" value="<?=e($edit['course']??'BCA')?>"></label><label>Academic year<input required name="academic_year" value="<?=e($edit['academic_year']??'Year 1')?>"></label><label>Status<select name="status"><option value="active" <?=($edit['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><div><button class="btn" type="submit">Save student</button></div></form></section>
<section class="panel"><h2>Student records</h2><form method="get" class="inline-form"><input name="q" placeholder="Search name, email or code" value="<?=e($search)?>"><select name="course"><option value="">All courses</option><?php foreach($courses as $c): ?><option <?= $course===$c?'selected':'' ?> value="<?=e($c)?>"><?=e($c)?></option><?php endforeach; ?></select><button class="btn secondary">Search / Filter</button></form><div class="table-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>Email</th><th>Course</th><th>Year</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($students as $st): ?><tr><td><?=e($st['student_code'])?></td><td><?=e($st['full_name'])?></td><td><?=e($st['email'])?></td><td><?=e($st['course'])?></td><td><?=e($st['academic_year'])?></td><td><?=e($st['status'])?></td><td><a href="?edit=<?=(int)$st['id']?>">Edit</a><form method="post" style="display:inline" onsubmit="return confirm('Delete this student?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$st['id']?>"><button class="link-button">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$students): ?><tr><td colspan="7">No students found.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require __DIR__.'/inc/footer.php'; ?>
